    private boolean validacoes() {
        if (jTextFieldNomee.getText().trim().isEmpty()) {
            JOptionsPane.showMessageDialog(null, "O campo nome deve ser preenchido");
            jTextFieldNomee.requestFocus();
            return false;
        }

        if (jTextFieldCPF.getText().trim().isEmpty()) {
            JOptionsPane.showMessageDialog(null, "O campo CPF deve ser preenchido");
            jTextFieldCPF.requestFocus();
            return false;
        }

        if (!jRadioButtonMasculino.isSelected() && !jRadioButtonFeminino.isSelected()) {
            JOptionsPane.showMessageDialog(null, "O campo gênero deve ser preenchido");
            return false;
        }

        if (!jCheckBox.isSelected()) {
            JOptionsPane.showMessageDialog(null, "Os termos de utilização não foram aceitos");
            return false;
        }

        return true;
    }
